class Solution {
public:
    string countOfAtoms(string formula) {
        vector<map<string, int>> stk(1);
        int i = 0, n = formula.size();

        while (i < n) {
            if (formula[i] == '(') {
                stk.push_back({});
                i++;
            } else if (formula[i] == ')') {
                auto top = stk.back();
                stk.pop_back();
                i++;
                int start = i;
                while (i < n && isdigit(formula[i])) i++;
                int mult = (i > start) ? stoi(formula.substr(start, i - start)) : 1;
                for (auto& [elem, count] : top) {
                    stk.back()[elem] += count * mult;
                }
            } else {
                int start = i++;
                while (i < n && islower(formula[i])) i++;
                string elem = formula.substr(start, i - start);
                start = i;
                while (i < n && isdigit(formula[i])) i++;
                int count = (i > start) ? stoi(formula.substr(start, i - start)) : 1;
                stk.back()[elem] += count;
            }
        }

        string res = "";
        for (auto& [elem, count] : stk[0]) {
            res += elem;
            if (count > 1) res += to_string(count);
        }
        return res;
    }
};

class Solution {
    public String countOfAtoms(String formula) {
        Deque<Map<String, Integer>> stack = new ArrayDeque<>();
        stack.push(new TreeMap<>());
        int i = 0, n = formula.length();

        while (i < n) {
            char c = formula.charAt(i);
            if (c == '(') {
                stack.push(new TreeMap<>());
                i++;
            } else if (c == ')') {
                Map<String, Integer> top = stack.pop();
                i++;
                int start = i;
                while (i < n && Character.isDigit(formula.charAt(i))) i++;
                int mult = (i > start) ? Integer.parseInt(formula.substring(start, i)) : 1;
                for (Map.Entry<String, Integer> entry : top.entrySet()) {
                    stack.peek().put(entry.getKey(), stack.peek().getOrDefault(entry.getKey(), 0) + entry.getValue() * mult);
                }
            } else {
                int start = i++;
                while (i < n && Character.isLowerCase(formula.charAt(i))) i++;
                String elem = formula.substring(start, i);
                start = i;
                while (i < n && Character.isDigit(formula.charAt(i))) i++;
                int count = (i > start) ? Integer.parseInt(formula.substring(start, i)) : 1;
                stack.peek().put(elem, stack.peek().getOrDefault(elem, 0) + count);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> entry : stack.peek().entrySet()) {
            sb.append(entry.getKey());
            if (entry.getValue() > 1) sb.append(entry.getValue());
        }
        return sb.toString();
    }
}

var countOfAtoms = function(formula) {
    const stack = [new Map()];
    let i = 0, n = formula.length;

    while (i < n) {
        if (formula[i] === '(') {
            stack.push(new Map());
            i++;
        } else if (formula[i] === ')') {
            const top = stack.pop();
            i++;
            const start = i;
            while (i < n && /\d/.test(formula[i])) i++;
            const mult = (i > start) ? parseInt(formula.slice(start, i), 10) : 1;
            const target = stack[stack.length - 1];
            for (const [elem, count] of top.entries()) {
                target.set(elem, (target.get(elem) || 0) + count * mult);
            }
        } else {
            const startElem = i++;
            while (i < n && /[a-z]/.test(formula[i])) i++;
            const elem = formula.slice(startElem, i);
            const startCount = i;
            while (i < n && /\d/.test(formula[i])) i++;
            const count = (i > startCount) ? parseInt(formula.slice(startCount, i), 10) : 1;
            const target = stack[stack.length - 1];
            target.set(elem, (target.get(elem) || 0) + count);
        }
    }

    const finalMap = stack[0];
    const sortedKeys = Array.from(finalMap.keys()).sort();
    let res = '';
    for (const key of sortedKeys) {
        res += key;
        const val = finalMap.get(key);
        if (val > 1) res += val;
    }
    return res;
};
